<?php
require_once __DIR__.'/common.php';
$id=(int)app_value($_GET,'id_mensaje');$message=fm_message($id);
$replies=app_rows('SELECT r.*,CONCAT_WS(" ",u.Nombre,u.Apellido1,u.Apellido2) AS autor FROM agenda_notas_padres_respuestas r LEFT JOIN usuarios u ON u.id_usuario=r.respondido_por WHERE r.id_nota=? ORDER BY r.fecha_respuesta,r.hora_respuesta,r.id_respuesta','i',[$id]);
fm_header($message['asunto']?:'Conversación con la familia');
?>
<div class="fm-conversation"><p class="fm-student">Familia de <?=app_escape($message['alumno']?:'Alumno archivado')?></p><div class="fm-actions"><a class="quiet" href="bandeja.php?id_alumno=<?=(int)$message['id_alumno']?>">Todas sus conversaciones</a><span class="fm-badge"><?=(int)$message['destino']===1?'Administración':'Equipo de piscina'?></span><?php if($message['pendiente']){?><form method="post" action="acciones.php"><?php fm_post_fields('read',$id);?><button class="quiet">Marcar como leído</button></form><span class="fm-badge pending">Pendiente de leer</span><?php }?></div>
<article class="fm-bubble <?=(int)$message['tipo_nota']===2?'staff':'family'?>"><header><strong><?=app_escape($message['remitente']?:((int)$message['tipo_nota']===2?'Equipo de piscina':'Familia'))?></strong><span class="fm-muted"><?=app_escape(fm_date($message['fecha'],$message['hora']))?></span></header><div class="fm-text"><?=app_escape(fm_plain($message['texto_nota']))?></div><?php if((int)$message['tipo_nota']===1){?><div class="fm-instructions"><strong>Instrucciones conservadas en el historial</strong><p><?=app_escape($message['medicamento'].' · '.$message['cantidad'])?></p><p><?=app_escape(fm_date($message['fecha_medicacion'],$message['hora_medicacion']))?> hasta <?=app_escape(fm_date($message['fecha_fin_medicacion']))?></p></div><?php }?></article>
<?php foreach($replies as $reply){?><article class="fm-bubble <?=(int)$reply['direccion']===1?'staff':'family'?>"><header><strong><?=app_escape($reply['autor']?:((int)$reply['direccion']===1?'Equipo de piscina':'Familia'))?></strong><span class="fm-muted"><?=app_escape(fm_date($reply['fecha_respuesta'],$reply['hora_respuesta']))?></span></header><div class="fm-text"><?=app_escape(fm_plain($reply['texto_respuesta']))?></div></article><?php }?>
<form class="fm-compose" id="respuesta" method="post" action="acciones.php"><h2>Responder a la familia</h2><?php fm_post_fields('reply',$id);fm_input('id_alumno',(int)$message['id_alumno']);?><label>Mensaje<textarea name="text" maxlength="12000" rows="5" required placeholder="Escribe una respuesta para la familia…"></textarea></label><p class="fm-muted">La respuesta aparecerá en la app de la familia dentro de esta conversación.</p><button class="primary">Enviar respuesta</button></form></div>
<?php fm_footer(); ?>
